test('invoiceTotals: with voucher', () => {
  const result = invoiceTotals({
    lines: [
      {
        sku: 'SKU',
        name: 'Item',
        qty: 5,
        unitPrice: 100,
        vatRate: 21,
        discountPercent: 10,
      },
    ],
    voucher: { code: 'SAVE50', amount: 50 },
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.voucher, 50);
  // Subtotal: 500, discount: 50, VAT: 94, total: 544, after voucher: 494
  assert.equal(result.value.total, 494);
});

test('invoiceTotals: large invoice with many lines', () => {
  const lines = [];
  for (let i = 0; i < 100; i++) {
    lines.push({
      sku: `SKU-${i}`,
      name: `Item ${i}`,
      qty: 10,
      unitPrice: 1000,
      vatRate: 21,
    });
  }

  const result = invoiceTotals({ lines });

  assert.equal(result.ok, true);
  assert(result.value.subtotal > 0);
  assert(result.value.vat > 0);
  assert(result.value.total > 0);
});

test('lineDiscount: bulk discount for qty >= 10', () => {
  const result = lineDiscount({ qty: 10, unitPrice: 100 });
  // Line total: 1000, no line discount, bulk 2.5%: 25
  assert.equal(result.ok, true);
  assert.equal(result.value, 25);
});

test('lineDiscount: no bulk discount for qty < 10', () => {
  const result = lineDiscount({ qty: 9, unitPrice: 100 });
  // Line total: 900, no line discount, no bulk discount
  assert.deepEqual(result, { ok: true, value: 0 });
});

test('lineDiscount: bulk discount applied after line discount', () => {
  const result = lineDiscount({ qty: 10, unitPrice: 100, discountPercent: 10 });
  // Line total: 1000, line discount 10%: 100, remaining: 900
  // Bulk discount 2.5% of 900: 22.5 → 22
  // Total: 100 + 22 = 122
  assert.equal(result.ok, true);
  assert.equal(result.value, 122);
});

test('lineDiscount: bulk discount with various line discounts', () => {
  // 50% line discount
  const result = lineDiscount({ qty: 10, unitPrice: 100, discountPercent: 50 });
  // Line total: 1000, line discount: 500, remaining: 500
  // Bulk discount 2.5% of 500: 12.5 → 12
  // Total: 500 + 12 = 512
  assert.equal(result.ok, true);
  assert.equal(result.value, 512);
});

test('lineDiscount: bulk discount with qty exactly 10', () => {
  const result = lineDiscount({ qty: 10, unitPrice: 100 });
  assert.equal(result.ok, true);
  assert(result.value > 0);
});

test('lineDiscount: bulk discount with large qty', () => {
  const result = lineDiscount({ qty: 100, unitPrice: 100 });
  // Line total: 10000, no line discount, bulk 2.5%: 250
  assert.equal(result.ok, true);
  assert.equal(result.value, 250);
});

test('lineDiscount: bulk discount with large qty and line discount', () => {
  const result = lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 20 });
  // Line total: 10000, line discount 20%: 2000, remaining: 8000
  // Bulk discount 2.5% of 8000: 200
  // Total: 2000 + 200 = 2200
  assert.equal(result.ok, true);
  assert.equal(result.value, 2200);
});

test('lineVat: VAT calculated after bulk discount', () => {
  const result = lineVat({ qty: 10, unitPrice: 100, vatRate: 21 });
  // Line total: 1000, no line discount, bulk discount 2.5%: 25
  // Amount after discount: 975, VAT 21%: 204.75 → 205
  assert.equal(result.ok, true);
  assert.equal(result.value, 205);
});

test('lineVat: VAT with bulk discount and line discount', () => {
  const result = lineVat({ qty: 10, unitPrice: 100, discountPercent: 10, vatRate: 21 });
  // Line total: 1000, line discount 10%: 100, remaining: 900
  // Bulk discount 2.5% of 900: 22, remaining: 878
  // VAT 21% of 878: 184.38 → 184
  assert.equal(result.ok, true);
  assert.equal(result.value, 184);
});

test('invoiceTotals: with bulk discount', () => {
  const result = invoiceTotals({
    lines: [
      {
        sku: 'SKU',
        name: 'Item',
        qty: 10,
        unitPrice: 100,
        vatRate: 21,
      },
    ],
  });

  assert.equal(result.ok, true);
  // Line total: 1000, no line discount, bulk discount 2.5%: 25
  // Amount: 975, VAT: 205
  assert.equal(result.value.subtotal, 1000);
  assert.equal(result.value.discount, 25);
  assert.equal(result.value.vat, 205);
  assert.equal(result.value.total, 1180);
});

test('invoiceTotals: with bulk discount and line discount', () => {
  const result = invoiceTotals({
    lines: [
      {
        sku: 'SKU',
        name: 'Item',
        qty: 20,
        unitPrice: 100,
        discountPercent: 10,
        vatRate: 21,
      },
    ],
  });

  assert.equal(result.ok, true);
  // Line total: 2000, line discount 10%: 200, remaining: 1800
  // Bulk discount 2.5% of 1800: 45
  // Total discount: 200 + 45 = 245
  // Amount: 1755, VAT 21%: 368.55 → 369
  assert.equal(result.value.subtotal, 2000);
  assert.equal(result.value.discount, 245);
  assert.equal(result.value.vat, 369);
  assert.equal(result.value.total, 2124);
});

test('invoiceTotals: mixed - some lines with bulk discount, some without', () => {
  const result = invoiceTotals({
    lines: [
      {
        sku: 'SKU1',
        name: 'Item 1',
        qty: 5,
        unitPrice: 100,
        vatRate: 21,
      },
      {
        sku: 'SKU2',
        name: 'Item 2',
        qty: 15,
        unitPrice: 100,
        vatRate: 21,
      },
    ],
  });

  assert.equal(result.ok, true);
  // Line 1: total 500, no discount, VAT: 105
  // Line 2: total 1500, bulk discount 2.5%: 37.5 → 38, VAT: 314.52 → 315
  // Total discount: 38
  assert.equal(result.value.subtotal, 2000);
  assert.equal(result.value.discount, 38);
  assert(result.value.total > 0);
});

test('lineDiscount: bulk discount rounded correctly', () => {
  const result = lineDiscount({ qty: 10, unitPrice: 10 });
  // Line total: 100, no line discount, bulk 2.5%: 2.5 → 2 (banker's rounding)
  assert.equal(result.ok, true);
  assert.equal(result.value, 2);
});

test('lineDiscount: bulk discount with fractional results', () => {
  const result = lineDiscount({ qty: 10, unitPrice: 33 });
  // Line total: 330, no line discount, bulk 2.5%: 8.25 → 8
  assert.equal(result.ok, true);
  assert.equal(result.value, 8);
});

test('invoiceTotals: bulk discount does not affect items with qty < 10', () => {
  const result1 = invoiceTotals({
    lines: [
      { sku: 'SKU', name: 'Item', qty: 9, unitPrice: 100, vatRate: 21 },
    ],
  });

  const result2 = invoiceTotals({
    lines: [
      { sku: 'SKU', name: 'Item', qty: 10, unitPrice: 100, vatRate: 21 },
    ],
  });

  assert.equal(result1.ok, true);
  assert.equal(result2.ok, true);
  assert.equal(result1.value.discount, 0);
  assert(result2.value.discount > 0);
});

test('lineDiscount: bulk discount with 100% line discount', () => {
  const result = lineDiscount({ qty: 10, unitPrice: 100, discountPercent: 100 });
  // Line total: 1000, line discount 100%: 1000, remaining: 0
  // Bulk discount 2.5% of 0: 0
  // Total: 1000
  assert.equal(result.ok, true);
  assert.equal(result.value, 1000);
});

test('lineVat: VAT zero for 0% rate with bulk discount', () => {
  const result = lineVat({ qty: 10, unitPrice: 100, vatRate: 0 });
  // Line total: 1000, bulk discount: 25, amount: 975
  // VAT 0%: 0
  assert.deepEqual(result, { ok: true, value: 0 });
});

