1	import { ok, fail } from './result.js';
2	import { getCustomer, normalizeId, TIER_DISCOUNTS } from './customers.js';
3	import { getProduct } from './catalogue.js';
4	import { nextInvoiceNumber } from './numbering.js';
5	import { isValidDate, addDays } from './dates.js';
6	import { lineTotal, lineDiscount, lineVat, invoiceTotals, isValidDiscount } from './totals.js';
