10	function calculateDueDate(issueDate, terms) {
11	  if (terms === 'NET14') return addDays(issueDate, 14);
12	  if (terms === 'NET30') return addDays(issueDate, 30);
13	  if (terms === 'EOM') {
14	    const date = new Date(issueDate + 'T00:00:00Z');
15	    const lastDay = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 0));
16	    return lastDay.toISOString().slice(0, 10);
17	  }
18	  return null;
19	}
