21	/**
22	 * Create an invoice with the given customer, date, and line items.
23	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
24	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms?: string, dueDate?: string } } | { ok: false, error: string }}
25	 */
26	export function createInvoice({ customerId, issueDate, lines, terms }) {
27	  const normalizedCustomerId = normalizeId(customerId);
28	  const customerResult = getCustomer(normalizedCustomerId);
29	  if (!customerResult.ok) return customerResult;
30	  const customer = customerResult.value;
31	
32	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
33	
34	  const finalTerms = terms ?? 'NET30';
35	  if (!['NET14', 'NET30', 'EOM'].includes(finalTerms)) {
36	    return fail('TERMS_INVALID');
37	  }
38	  const dueDate = calculateDueDate(issueDate, finalTerms);
39	
40	  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');
41	
42	  const invoiceLines = [];
43	  for (const line of lines) {
44	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
45	
46	    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
47	      return fail('DISCOUNT_INVALID');
48	    }
49	
50	    const productResult = getProduct(line.sku);
51	    if (!productResult.ok) return productResult;
52	
53	    const product = productResult.value;
54	    const invoiceLine = {
55	      sku: line.sku,
56	      name: product.name,
57	      qty: line.qty,
58	      unitPrice: product.unitPrice,
59	      vatRate: product.vatRate,
60	    };
61	
62	    if (line.discountPercent !== undefined) {
63	      invoiceLine.discountPercent = line.discountPercent;
64	    } else {
65	      const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
66	      if (tierDiscount > 0) {
67	        invoiceLine.discountPercent = tierDiscount;
68	      }
69	    }
70	
71	    invoiceLines.push(invoiceLine);
72	  }
73	
74	  const invoice = {
75	    customerId: normalizedCustomerId,
76	    issueDate,
77	    status: 'draft',
78	    lines: invoiceLines,
79	  };
80	
81	  if (finalTerms !== 'NET30') {
82	    invoice.terms = finalTerms;
83	  }
84	  invoice.dueDate = dueDate;
85	
86	  return ok(invoice);
87	}
