89	/**
90	 * Add or update a line on a draft invoice.
91	 * If the SKU already exists, increase its quantity; otherwise add a new line.
92	 * @param {{ status: string, lines: Array }} invoice
93	 * @param {{ sku: string, qty: number, discountPercent?: number }}
94	 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
95	 */
96	export function addLine(invoice, { sku, qty, discountPercent }) {
97	  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');
98	
99	  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');
100	
101	  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
102	    return fail('DISCOUNT_INVALID');
103	  }
104	
105	  const customerResult = getCustomer(invoice.customerId);
106	  if (!customerResult.ok) return customerResult;
107	  const customer = customerResult.value;
108	
109	  const productResult = getProduct(sku);
110	  if (!productResult.ok) return productResult;
111	
112	  const product = productResult.value;
113	  const newLines = invoice.lines.map((line) => ({ ...line }));
114	
115	  const existingIndex = newLines.findIndex((line) => line.sku === sku);
116	  if (existingIndex >= 0) {
117	    newLines[existingIndex] = { ...newLines[existingIndex], qty: newLines[existingIndex].qty + qty };
118	    if (discountPercent !== undefined) {
119	      newLines[existingIndex].discountPercent = discountPercent;
120	    }
121	  } else {
122	    const newLine = {
123	      sku,
124	      name: product.name,
125	      qty,
126	      unitPrice: product.unitPrice,
127	      vatRate: product.vatRate,
128	    };
129	    if (discountPercent !== undefined) {
130	      newLine.discountPercent = discountPercent;
131	    } else {
132	      const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
133	      if (tierDiscount > 0) {
134	        newLine.discountPercent = tierDiscount;
135	      }
136	    }
137	    newLines.push(newLine);
138	  }
139	
140	  return ok({
141	    ...invoice,
142	    lines: newLines,
143	  });
144	}
