146	/**
147	 * Remove a line from a draft invoice.
148	 * @param {{ status: string, lines: Array }} invoice
149	 * @param {string} sku
150	 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
151	 */
152	export function removeLine(invoice, sku) {
153	  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');
154	
155	  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
156	  if (lineIndex < 0) return fail('LINE_NOT_FOUND');
157	
158	  if (invoice.lines.length === 1) return fail('NO_LINES');
159	
160	  const newLines = invoice.lines.filter((line) => line.sku !== sku);
161	
162	  return ok({
163	    ...invoice,
164	    lines: newLines,
165	  });
166	}
