168	/**
169	 * Apply a voucher to a draft invoice.
170	 * @param {{ status: string, voucher?: { code: string, amount: number } }} invoice
171	 * @param {{ code: string, amount: number }}
172	 * @returns {{ ok: true, value: { voucher: { code: string, amount: number } } } | { ok: false, error: string }}
173	 */
174	export function applyVoucher(invoice, { code, amount }) {
175	  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');
176	
177	  if (invoice.voucher) return fail('VOUCHER_EXISTS');
178	
179	  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');
180	
181	  return ok({
182	    ...invoice,
183	    voucher: { code, amount },
184	  });
185	}
