187	/**
188	 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
189	 * @param {{ status: string, issueDate: string, lines: Array }} invoice
190	 * @param {Array<string>} existingNumbers
191	 * @returns {{ ok: true, value: { number: string, status: string } } | { ok: false, error: string }}
192	 */
193	export function issueInvoice(invoice, existingNumbers) {
194	  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');
195	
196	  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
197	
198	  return ok({
199	    ...invoice,
200	    number,
201	    status: 'issued',
202	  });
203	}
