8	/**
9	 * Calculate the total amount for a line item (qty × unitPrice).
10	 * @param {{ qty: number, unitPrice: number }}
11	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
12	 */
13	export function lineTotal(line) {
14	  if (!line || !Number.isInteger(line.qty) || line.qty <= 0) {
15	    return fail('LINE_INVALID');
16	  }
17	  if (typeof line.unitPrice !== 'number' || line.unitPrice < 0) {
18	    return fail('LINE_INVALID');
19	  }
20	  return ok(line.qty * line.unitPrice);
21	}
