23	/**
24	 * Calculate the discount amount for a line item (includes bulk discount for qty >= 10).
25	 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
26	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
27	 */
28	export function lineDiscount(line) {
29	  const totalResult = lineTotal(line);
30	  if (!totalResult.ok) return totalResult;
31	
32	  let lineTotal_ = totalResult.value;
33	  let totalDiscount = 0;
34	
35	  if (line.discountPercent) {
36	    if (!isValidDiscount(line.discountPercent)) {
37	      return fail('DISCOUNT_INVALID');
38	    }
39	    const discount = roundCents(lineTotal_ * line.discountPercent / 100);
40	    totalDiscount += discount;
41	    lineTotal_ -= discount;
42	  }
43	
44	  if (line.qty >= 10) {
45	    const bulkDiscount = roundCents(lineTotal_ * 2.5 / 100);
46	    totalDiscount += bulkDiscount;
47	  }
48	
49	  return ok(Math.max(0, totalDiscount));
50	}
