52	/**
53	 * Calculate the VAT amount for a line item.
54	 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }}
55	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
56	 */
57	export function lineVat(line) {
58	  const totalResult = lineTotal(line);
59	  if (!totalResult.ok) return totalResult;
60	
61	  const discountResult = lineDiscount(line);
62	  if (!discountResult.ok) return discountResult;
63	
64	  const amountAfterDiscount = totalResult.value - discountResult.value;
65	  if (typeof line.vatRate !== 'number' || line.vatRate < 0) {
66	    return fail('LINE_INVALID');
67	  }
68	
69	  const vat = roundCents(amountAfterDiscount * line.vatRate / 100);
70	  return ok(Math.max(0, vat));
71	}
72	
73	/**
74	 * Calculate totals for an invoice: subtotal, discount, VAT, voucher, and total.
75	 * @param {{ lines: Array, voucher?: { code: string, amount: number } }}
76	 * @returns {{ ok: true, value: { subtotal: number, discount: number, vat: number, voucher: number, total: number } } | { ok: false, error: string }}
77	 */
78	export function invoiceTotals(invoice) {
79	  if (!invoice || !Array.isArray(invoice.lines)) {
80	    return fail('INVOICE_INVALID');
81	  }
82	
83	  let subtotal = 0;
84	  let discount = 0;
85	  let vat = 0;
86	
87	  for (const line of invoice.lines) {
88	    const totalResult = lineTotal(line);
89	    if (!totalResult.ok) return totalResult;
90	    subtotal += totalResult.value;
91	
92	    const discountResult = lineDiscount(line);
93	    if (!discountResult.ok) return discountResult;
94	    discount += discountResult.value;
95	
96	    const vatResult = lineVat(line);
97	    if (!vatResult.ok) return vatResult;
98	    vat += vatResult.value;
99	  }
100	
101	  const voucher = invoice.voucher?.amount ?? 0;
102	  const total = Math.max(0, subtotal - discount + vat - voucher);
103	
104	  return ok({ subtotal, discount, vat, voucher, total });
105	}
